export function renderCatalogModule(simpleIconsLibrary, phosphorLibrary) {
  const libraryModule = (name, library) => [
    '// Generated by scripts/generate-icon-catalog.mjs. Do not edit.',
    '// Keep catalog data out of bundlers’ object-literal ASTs; decode once on lazy import.',
    `export const ${name} = JSON.parse(${JSON.stringify(JSON.stringify(library))});`,
    '',
  ].join('\n');
  return {
    'simple-icons.js': libraryModule('simpleIconsLibrary', simpleIconsLibrary),
    'phosphor.js': libraryModule('phosphorLibrary', phosphorLibrary),
    'icon-libraries.js': [
      '// Generated by scripts/generate-icon-catalog.mjs. Do not edit.',
      "export { simpleIconsLibrary } from './simple-icons.js';",
      "export { phosphorLibrary } from './phosphor.js';",
      '',
    ].join('\n'),
  };
}
